    print("  help      : Show help")
    print("  histogram : Dump histogram of file sizes found.")
    print("  index     : Scan the filesystem and generate the Duc index")
    print("  info      : Dump database info")
    print("  ls        : List sizes of directory")
    print("  topn      : Dump N largest files in DB.")
    print("  xml       : Dump XML output")
    print("  json      : Dump JSON output")
