    for p_arg in args.path:
        path = os.path.abspath(p_arg)
        files_count, dirs_count, all_entries = 0, 0, {}
        for root, dirs, files in os.walk(path):
            rel_root = os.path.abspath(root)
            try:
                st = os.lstat(rel_root)
                all_entries[rel_root] = {'parent': os.path.dirname(rel_root) if rel_root != path else "", 'name': os.path.basename(rel_root), 'is_dir': 1, 'size_actual': st.st_blocks * 512, 'size_apparent': st.st_size, 'inc_size_actual': st.st_blocks * 512, 'inc_size_apparent': st.st_size, 'count': 0}
                dirs_count += 1
            except OSError: continue
            for name in files:
                fpath = os.path.join(rel_root, name)
                try:
                    st = os.lstat(fpath)
                    all_entries[fpath] = {'parent': rel_root, 'name': name, 'is_dir': 0, 'size_actual': st.st_blocks * 512, 'size_apparent': st.st_size, 'inc_size_actual': st.st_blocks * 512, 'inc_size_apparent': st.st_size, 'count': 0}
