                except OSError: continue
        sorted_paths = sorted(all_entries.keys(), key=lambda p: p.count(os.sep), reverse=True)
        for p in sorted_paths:
            parent = all_entries[p]['parent']
            if parent in all_entries:
                all_entries[parent]['inc_size_actual'] += all_entries[p]['inc_size_actual']
                all_entries[parent]['inc_size_apparent'] += all_entries[p]['inc_size_apparent']
                all_entries[parent]['count'] += all_entries[p]['count'] + 1
