    for r in cursor.fetchall():
        print("%s %s %s %s %s" % (r[0], format_size_short(r[1]).strip().rjust(7), format_size_short(r[2]).strip().rjust(7), format_size_duc(r[3], 7), r[4]))
    conn.close()

def do_ls(args):
    if not os.path.exists(args.database): return
    conn = sqlite3.connect(args.database); cursor = conn.cursor()
    paths = [os.path.abspath(p) for p in args.path]
    if not paths:
        cursor.execute("SELECT path FROM reports ORDER BY date DESC LIMIT 1")
        row = cursor.fetchone()
        paths = [row[0]] if row else [os.getcwd()]
    for path in paths:
        if args.recursive: print_tree(cursor, path, args, "")
        else:
            cursor.execute("SELECT name, inc_size_actual, inc_size_apparent, is_dir FROM entries WHERE parent = ? ORDER BY " + ("name ASC" if args.name_sort else "inc_size_actual DESC"), (path,))
            rows = cursor.fetchall() or cursor.execute("SELECT name, size_actual, size_apparent, is_dir FROM entries WHERE path = ?", (path,)).fetchall()
            for r in rows:
                s = r[2] if args.apparent else r[1]
                print("%s %s" % (format_size_bytes(s) if args.bytes else format_size_duc(s), r[0]))
