    conn = sqlite3.connect(args.database); cursor = conn.cursor()
    path = os.path.abspath(args.path if args.path else os.getcwd())
    row = cursor.execute("SELECT inc_size_actual, inc_size_apparent, count FROM entries WHERE path = ?", (path,)).fetchone()
    if not row: return
    def get(p):
        res = []
        for r in cursor.execute("SELECT name, inc_size_actual, inc_size_apparent, is_dir, count, path FROM entries WHERE parent = ? ORDER BY inc_size_actual DESC", (p,)).fetchall():
            ent = {"name": r[0], "size_actual": r[1], "size_apparent": r[2]}
            if r[3]: ent.update({"type": "dir", "count": r[4], "children": get(r[5])})
            res.append(ent)
        return res
    print(json.dumps({"name": os.path.basename(path), "count": row[2], "size_apparent": row[1], "size_actual": row[0], "children": get(path)}, indent=2)); conn.close()

def do_topn(args):
    if not os.path.exists(args.database): return
    conn = sqlite3.connect(args.database); cursor = conn.cursor()
    path = os.path.abspath(args.path if args.path else os.getcwd())
    print("        Size Filename")
    for r in cursor.execute("SELECT path, size_actual FROM entries WHERE is_dir = 0 AND path LIKE ? ORDER BY size_actual DESC LIMIT 10", (path + "%",)).fetchall():
        print("%s %s" % (format_size_duc(r[1], 12), r[0]))
    conn.close()

def do_histogram(args):
    if not os.path.exists(args.database): return
    conn = sqlite3.connect(args.database); cursor = conn.cursor()
    path = os.path.abspath(args.path if args.path else os.getcwd()); buckets = [0] * 48
    for (s,) in cursor.execute("SELECT size_actual FROM entries WHERE is_dir = 0 AND path LIKE ?", (path + "%",)).fetchall():
        if s > 0:
            b = int(math.log2(s))
            if b < 48: buckets[b] += 1
    print("Path: %s\nBkt       Size      Count" % path)
    for i in range(48): print("%3d %10s %10d" % (i, format_size_duc(1<<i, 10).strip(), buckets[i]))
    conn.close()

if __name__ == '__main__':
    main()
